   26      public PaymentResult pay(PaymentRequest r) {
   27          if (!DEBITABLE.contains(r.accountType())) {
   28              return reject(50001, "TIPO DE CUENTA NO PERMITIDO");
   29          }
   30          List<String> status = jdbc.queryForList(
   31                  "SELECT status FROM orders WHERE order_no = ? AND company_id = ?", String.class,
   32                  r.orderId(), r.companyId());
   33          if (status.isEmpty()) {
   34              return reject(50002, "ORDEN NO EXISTE");
   35          }
   36          if (!"P".equals(status.get(0).trim())) {
   37              return reject(50003, "ORDEN NO ESTA PENDIENTE");
   38          }
   39  
   40          BigDecimal fee;
   41          boolean chargedApart;
   42          List<Map<String, Object>> companyFee = jdbc.queryForList(
   43                  "SELECT fee, charged_apart FROM company_fees WHERE company_id = ? AND service_code = ?",
   44                  r.companyId(), r.serviceCode());
   45          if (!companyFee.isEmpty()) {
   46              fee = (BigDecimal) companyFee.get(0).get("fee");
   47              chargedApart = "S".equals(String.valueOf(companyFee.get(0).get("charged_apart")).trim());
   48          } else {
   49              List<BigDecimal> serviceFee = jdbc.queryForList(
   50                      "SELECT fee FROM services WHERE code = ?", BigDecimal.class, r.serviceCode());
   51              fee = serviceFee.isEmpty() ? null : serviceFee.get(0);
   52              chargedApart = false;
   53          }
   54          if (fee == null) {
   55              fee = BigDecimal.ZERO;
   56          }
   57  
   58          String channel = r.channel() == null ? "WEB" : r.channel();
   59          BigDecimal commission = "WEB".equals(channel)
   60                  ? fee.divide(BigDecimal.valueOf(2)).setScale(2, RoundingMode.HALF_UP)
   61                  : fee;
   62          if ("NOMINA".equals(r.serviceCode())) {
   63              commission = BigDecimal.ZERO;
   64          }
   65          BigDecimal total = chargedApart ? r.amount() : r.amount().add(commission);
   66  
   67          List<BigDecimal> balance = jdbc.queryForList(
   68                  "SELECT balance FROM accounts WHERE account_no = ? AND account_type = ?", BigDecimal.class,
   69                  r.accountNumber(), r.accountType());
   70          if (!balance.isEmpty()) {
   71              BigDecimal available = "VIR".equals(r.accountType()) ? balance.get(0) : balance.get(0).add(OVERDRAFT);
   72              if (available.compareTo(total) < 0) {
   73                  return reject(50004, "FONDOS INSUFICIENTES");
   74              }
   75          }
   76  
   77          CoreBankingClient.Debit debit = core.debit(r.accountNumber(), r.accountType(), total, "PAGO ORDEN");
   78          if (debit.code() != 0) {
   79              return reject(50005, "ERROR EN DEBITO");
   80          }
   81          if (chargedApart && commission.signum() > 0) {
   82              CoreBankingClient.Debit second = core.debit(r.accountNumber(), r.accountType(), commission, "COMISION PAGO");
   83              if (second.code() != 0) {
   84                  return reject(50006, "ERROR EN COMISION");
   85              }
   86          }
   87  
   88          int updated = jdbc.update(
   89                  "UPDATE orders SET status = 'A', paid_at = ?, fee = ? WHERE order_no = ? AND company_id = ?",
   90                  r.processDate(), commission, r.orderId(), r.companyId());
   91          if (updated == 0) {
   92              return reject(50007, "ERROR ACTUALIZANDO ORDEN");
   93          }
   94          return new PaymentResult(0, debit.sequence(), "PAGO REALIZADO");
   95      }
